IF OBJECT_ID(N'dbo.tb_logradouro', N'U') IS NULL CREATE TABLE tb_logradouro (id_logradouro INT IDENTITY(1,1) NOT NULL PRIMARY KEY, cep VARCHAR(8) NOT NULL UNIQUE, nome VARCHAR(150) NOT NULL, bairro VARCHAR(100) NOT NULL, cidade VARCHAR(100) NOT NULL, estado CHAR(2) NOT NULL, pais VARCHAR(50) NOT NULL DEFAULT 'Brasil');
IF OBJECT_ID(N'dbo.tb_aluno', N'U') IS NULL CREATE TABLE tb_aluno (id_aluno INT IDENTITY(1,1) PRIMARY KEY, cpf VARCHAR(11) NOT NULL UNIQUE, nome VARCHAR(150) NOT NULL, nascimento DATE NOT NULL, telefone VARCHAR(15) NOT NULL, email VARCHAR(150) NOT NULL, logradouro_id INT NOT NULL, numero VARCHAR(20) NOT NULL, complemento VARCHAR(100) NULL, senha VARCHAR(255) NOT NULL, foto VARBINARY(MAX) NULL, FOREIGN KEY (logradouro_id) REFERENCES tb_logradouro(id_logradouro));
IF OBJECT_ID(N'dbo.tb_colaborador', N'U') IS NULL CREATE TABLE tb_colaborador (id_colaborador INT IDENTITY(1,1) PRIMARY KEY, cpf VARCHAR(11) NOT NULL UNIQUE, nome VARCHAR(150) NOT NULL, nascimento DATE NOT NULL, telefone VARCHAR(15) NOT NULL, email VARCHAR(150) NOT NULL, logradouro_id INT NOT NULL, numero VARCHAR(20) NOT NULL, complemento VARCHAR(100) NULL, senha VARCHAR(255) NOT NULL, foto VARBINARY(MAX) NULL, admissao DATE NOT NULL, tipo INT NOT NULL, vinculo INT NOT NULL, FOREIGN KEY (logradouro_id) REFERENCES tb_logradouro(id_logradouro));
IF OBJECT_ID(N'dbo.tb_matricula', N'U') IS NULL CREATE TABLE tb_matricula (id_matricula INT IDENTITY(1,1) PRIMARY KEY, aluno_id INT NOT NULL, plano INT NOT NULL, data_inicio DATE NOT NULL, data_fim DATE NOT NULL, objetivo VARCHAR(500) NOT NULL, restricao_medica INT NOT NULL DEFAULT 0, obs_restricao VARCHAR(500) NULL, laudo_medico VARBINARY(MAX) NULL, FOREIGN KEY (aluno_id) REFERENCES tb_aluno(id_aluno));
IF OBJECT_ID(N'dbo.tb_acesso', N'U') IS NULL CREATE TABLE tb_acesso (id_acesso INT IDENTITY(1,1) PRIMARY KEY, pessoa_tipo INT NOT NULL, pessoa_id INT NOT NULL, data_hora DATETIME NOT NULL DEFAULT GETDATE());